1	import { feature } from 'bun:bundle'
2	import type { BetaContentBlock } from '@anthropic-ai/sdk/resources/beta/messages/messages.mjs'
3	import type {
4	  ImageBlockParam,
5	  TextBlockParam,
6	  ThinkingBlockParam,
7	  ToolResultBlockParam,
8	  ToolUseBlockParam,
9	} from '@anthropic-ai/sdk/resources/index.mjs'
10	import * as React from 'react'
11	import type { Command } from '@thyrox/command-runtime/runtime'
12	import { useTerminalSize } from '@anthropic/ink'
13	import { Box } from '@anthropic/ink'
14	import type { Tools } from '@thyrox/tool-registry/Tool.js'
15	import {
16	  type ConnectorTextBlock,
17	  isConnectorTextBlock,
18	} from '@thyrox/provider/connectorTextTypes'
19	import type {
20	  AssistantMessage,
21	  AttachmentMessage as AttachmentMessageType,
22	  CollapsedReadSearchGroup as CollapsedReadSearchGroupType,
23	  GroupedToolUseMessage as GroupedToolUseMessageType,
24	  NormalizedUserMessage,
25	  ProgressMessage,
26	  SystemMessage,
27	} from '@thyrox/agent/messageShapes'
28	import { type AdvisorBlock, isAdvisorBlock } from '@thyrox/provider/advisor.js'
29	import { isFullscreenEnvEnabled } from '../fullscreen.js'
30	import { logError } from '@thyrox/local-observability/logging'
31	import type { buildMessageLookups } from '@thyrox/agent/messages.js'
32	import { CompactSummary } from './CompactSummary.js'
33	import { AdvisorMessage } from './messages/AdvisorMessage.js'
34	import { AssistantRedactedThinkingMessage } from './messages/AssistantRedactedThinkingMessage.js'
35	import { AssistantTextMessage } from './messages/AssistantTextMessage.js'
36	import { AssistantThinkingMessage } from './messages/AssistantThinkingMessage.js'
37	import { AssistantToolUseMessage } from './messages/AssistantToolUseMessage.js'
38	import { AttachmentMessage } from './messages/AttachmentMessage.js'
39	import { CollapsedReadSearchContent } from './messages/CollapsedReadSearchContent.js'
40	import { CompactBoundaryMessage } from './messages/CompactBoundaryMessage.js'
41	import { GroupedToolUseContent } from './messages/GroupedToolUseContent.js'
42	import { SystemTextMessage } from './messages/SystemTextMessage.js'
43	import { UserImageMessage } from './messages/UserImageMessage.js'
44	import { UserTextMessage } from './messages/UserTextMessage.js'
45	import { UserToolResultMessage } from './messages/UserToolResultMessage/UserToolResultMessage.js'
46	import { OffscreenFreeze } from './OffscreenFreeze.js'
47	import { ExpandShellOutputProvider } from './shell/ExpandShellOutputContext.js'
48	
49	export type Props = {
50	  message:
51	    | NormalizedUserMessage
52	    | AssistantMessage
53	    | AttachmentMessageType
54	    | SystemMessage
55	    | GroupedToolUseMessageType
56	    | CollapsedReadSearchGroupType
57	  lookups: ReturnType<typeof buildMessageLookups>
58	  // TODO: Find a way to remove this, and leave spacing to the consumer
59	  /** Absolute width for the container Box. When provided, eliminates a wrapper Box in the caller. */
60	  containerWidth?: number
61	  addMargin: boolean
62	  tools: Tools
63	  commands: Command[]
64	  verbose: boolean
65	  inProgressToolUseIDs: Set<string>
66	  progressMessagesForMessage: ProgressMessage[]
67	  shouldAnimate: boolean
68	  shouldShowDot: boolean
69	  style?: 'condensed'
70	  width?: number | string
71	  isTranscriptMode: boolean
72	  isStatic: boolean
73	  onOpenRateLimitOptions?: () => void
74	  isActiveCollapsedGroup?: boolean
75	  isUserContinuation?: boolean
76	  /** ID of the last thinking block (uuid:index) to show, used for hiding past thinking in transcript mode */
77	  lastThinkingBlockId?: string | null
78	  /** UUID of the latest user bash output message (for auto-expanding) */
79	  latestBashOutputUUID?: string | null
80	}
81	
82	function MessageImpl({
83	  message,
84	  lookups,
85	  containerWidth,
86	  addMargin,
87	  tools,
88	  commands,
89	  verbose,
90	  inProgressToolUseIDs,
91	  progressMessagesForMessage,
92	  shouldAnimate,
93	  shouldShowDot,
94	  style,
95	  width,
96	  isTranscriptMode,
97	  onOpenRateLimitOptions,
98	  isActiveCollapsedGroup,
99	  isUserContinuation = false,
100	  lastThinkingBlockId,
101	  latestBashOutputUUID,
102	}: Props): React.ReactNode {
103	  switch (message.type) {
104	    case 'attachment':
105	      return (
106	        <AttachmentMessage
107	          addMargin={addMargin}
108	          attachment={message.attachment}
109	          verbose={verbose}
110	          isTranscriptMode={isTranscriptMode}
111	        />
112	      )
113	    case 'assistant':
114	      return (
115	        <Box flexDirection="column" width={containerWidth ?? '100%'}>
116	          {(message.message.content ?? []).map((_: ConnectorTextBlock|TextBlockParam|ImageBlockParam|ThinkingBlockParam|ToolUseBlockParam|ToolResultBlockParam|BetaContentBlock|AdvisorBlock, index: React.Key|null|undefined) => (
117	            <AssistantMessageBlock
118	              key={index}
119	              param={_}
120	              addMargin={addMargin}
121	              tools={tools}
122	              commands={commands}
123	              verbose={verbose}
124	              inProgressToolUseIDs={inProgressToolUseIDs}
125	              progressMessagesForMessage={progressMessagesForMessage}
126	              shouldAnimate={shouldAnimate}
127	              shouldShowDot={shouldShowDot}
128	              width={width}
129	              inProgressToolCallCount={inProgressToolUseIDs.size}
130	              isTranscriptMode={isTranscriptMode}
131	              lookups={lookups}
132	              onOpenRateLimitOptions={onOpenRateLimitOptions}
133	              thinkingBlockId={`${message.uuid}:${index}`}
134	              lastThinkingBlockId={lastThinkingBlockId}
135	              advisorModel={message.advisorModel as string | undefined}
136	            />
137	          ))}
138	        </Box>
139	      )
140	    case 'user': {
141	      if (message.isCompactSummary) {
142	        return (
143	          <CompactSummary
144	            message={message}
145	            screen={isTranscriptMode ? 'transcript' : 'prompt'}
146	          />
147	        )
148	      }
149	      // Precompute the imageIndex prop for each content block. The previous
150	      // version incremented a counter inside the .map() callback, which
151	      // React Compiler bails on ("UpdateExpression to variables captured
152	      // within lambdas"). A plain for loop keeps the mutation out of a
153	      // closure so the compiler can memoize MessageImpl.
154	      const imageIndices: number[] = []
155	      let imagePosition = 0
156	      // `imagePasteIds` no esta declarado en `UserMessage`: llega por la firma
157	      // de indice de `MessageBase`, o sea `unknown`. Mismo estrechamiento que
158	      // `PromptInput.tsx:3205`.
159	      const imagePasteIds = message.imagePasteIds as number[] | undefined
160	      for (const param of message.message.content) {
161	        if (param.type === 'image') {
162	          const id = imagePasteIds?.[imagePosition]
163	          imagePosition++
164	          imageIndices.push(id ?? imagePosition)
165	        } else {
166	          imageIndices.push(imagePosition)
167	        }
168	      }
169	      // Check if this message is the latest bash output - if so, wrap content
170	      // with provider so OutputLine can show full output via context
171	      const isLatestBashOutput = latestBashOutputUUID === message.uuid
172	      const content = (
173	        <Box flexDirection="column" width={containerWidth ?? '100%'}>
174	          {message.message.content.map((param, index) => (
175	            <UserMessage
176	              key={index}
177	              message={message}
178	              addMargin={addMargin}
179	              tools={tools}
180	              progressMessagesForMessage={progressMessagesForMessage}
181	              param={param}
182	              style={style}
183	              verbose={verbose}
184	              imageIndex={imageIndices[index]!}
185	              isUserContinuation={isUserContinuation}
186	              lookups={lookups}
187	              isTranscriptMode={isTranscriptMode}
188	            />
189	          ))}
190	        </Box>
191	      )
192	      return isLatestBashOutput ? (
193	        <ExpandShellOutputProvider>{content}</ExpandShellOutputProvider>
194	      ) : (
195	        content
196	      )
197	    }
198	    case 'system':
199	      if (message.subtype === 'compact_boundary') {
200	        // Fullscreen keeps pre-compact messages in the ScrollBox (REPL.tsx
201	        // appends instead of resetting, Messages.tsx skips the boundary
202	        // filter) — scroll up for history, no need for the ctrl+o hint.
203	        if (isFullscreenEnvEnabled()) {
204	          return null
205	        }
206	        return <CompactBoundaryMessage />
207	      }
208	      if (message.subtype === 'microcompact_boundary') {
209	        // Logged at creation time in createMicrocompactBoundaryMessage
210	        return null
211	      }
212	      if (feature('HISTORY_SNIP')) {
213	        /* eslint-disable @typescript-eslint/no-require-imports */
214	        const { isSnipBoundaryMessage } =
215	          require('@thyrox/agent/compaction/snipProjection.js') as typeof import('@thyrox/agent/compaction/snipProjection.js')
216	        const { isSnipMarkerMessage } =
217	          require('@thyrox/agent/compaction/snipCompact.js') as typeof import('@thyrox/agent/compaction/snipCompact.js')
218	        /* eslint-enable @typescript-eslint/no-require-imports */
219	        if (isSnipBoundaryMessage(message)) {
220	          /* eslint-disable @typescript-eslint/no-require-imports */
221	          const { SnipBoundaryMessage } =
222	            require('./messages/SnipBoundaryMessage.js') as typeof import('./messages/SnipBoundaryMessage.js')
223	          /* eslint-enable @typescript-eslint/no-require-imports */
224	          return <SnipBoundaryMessage message={message} />
225	        }
226	        if (isSnipMarkerMessage(message)) {
227	          // Internal registration marker — not user-facing. The boundary
228	          // message (above) is what shows when snips actually execute.
229	          return null
230	        }
231	      }
232	      if (message.subtype === 'local_command') {
233	        return (
234	          <UserTextMessage
235	            addMargin={addMargin}
236	            param={{ type: 'text', text: message.content }}
237	            verbose={verbose}
238	            isTranscriptMode={isTranscriptMode}
239	          />
240	        )
241	      }
242	      return (
243	        <SystemTextMessage
244	          message={message}
245	          addMargin={addMargin}
246	          verbose={verbose}
247	          isTranscriptMode={isTranscriptMode}
248	        />
249	      )
250	    case 'grouped_tool_use':
251	      return (
252	        <GroupedToolUseContent
253	          message={message}
254	          tools={tools}
255	          lookups={lookups}
256	          inProgressToolUseIDs={inProgressToolUseIDs}
257	          shouldAnimate={shouldAnimate}
258	        />
259	      )
260	    case 'collapsed_read_search':
261	      // OffscreenFreeze: the verb flips "Reading…"→"Read" when tools complete.
262	      // If the group has scrolled into scrollback by then, the update triggers
263	      // a full terminal reset (CC-1155). This component is never marked static
264	      // in prompt mode (shouldRenderStatically returns false to allow live
265	      // updates between API turns), so the memo can't help. Freeze when
266	      // offscreen — scrollback shows whatever state was visible when it left.
267	      return (
268	        <OffscreenFreeze>
269	          <CollapsedReadSearchContent
270	            message={message}
271	            inProgressToolUseIDs={inProgressToolUseIDs}
272	            shouldAnimate={shouldAnimate}
273	            // ctrl+o transcript mode should expand the group the same way
274	            // --verbose does, so recalled memories + tool details are visible.
275	            // AttachmentMessage.tsx's standalone relevant_memories branch
276	            // already checks (verbose || isTranscriptMode); this aligns the
277	            // collapsed-group path to match.
278	            verbose={verbose || isTranscriptMode}
279	            tools={tools}
280	            lookups={lookups}
281	            isActiveGroup={isActiveCollapsedGroup}
282	          />
283	        </OffscreenFreeze>
284	      )
285	  }
286	}
287	
288	function UserMessage({
289	  message,
290	  addMargin,
291	  tools,
292	  progressMessagesForMessage,
293	  param,
294	  style,
295	  verbose,
296	  imageIndex,
297	  isUserContinuation,
298	  lookups,
299	  isTranscriptMode,
300	}: {
301	  message: NormalizedUserMessage
302	  addMargin: boolean
303	  tools: Tools
304	  progressMessagesForMessage: ProgressMessage[]
305	  param:
306	    | TextBlockParam
307	    | ImageBlockParam
308	    | ToolUseBlockParam
309	    | ToolResultBlockParam
310	  style?: 'condensed'
311	  verbose: boolean
312	  imageIndex?: number
313	  isUserContinuation: boolean
314	  lookups: ReturnType<typeof buildMessageLookups>
315	  isTranscriptMode: boolean
316	}): React.ReactNode {
317	  const { columns } = useTerminalSize()
318	  switch (param.type) {
319	    case 'text':
320	      return (
321	        <UserTextMessage
322	          addMargin={addMargin}
323	          param={param}
324	          verbose={verbose}
325	          planContent={message.planContent as string | undefined}
326	          isTranscriptMode={isTranscriptMode}
327	          timestamp={message.timestamp as string | undefined}
328	        />
329	      )
330	    case 'image':
331	      // If previous message is user (text or image), this is a continuation - use connector
332	      // Otherwise this image starts a new user turn - use margin
333	      return (
334	        <UserImageMessage
335	          imageId={imageIndex}
336	          addMargin={addMargin && !isUserContinuation}
337	        />
338	      )
339	    case 'tool_result':
340	      return (
341	        <UserToolResultMessage
342	          param={param}
343	          message={message}
344	          lookups={lookups}
345	          progressMessagesForMessage={progressMessagesForMessage}
346	          style={style}
347	          tools={tools}
348	          verbose={verbose}
349	          width={columns - 5}
350	          isTranscriptMode={isTranscriptMode}
351	        />
352	      )
353	    default:
354	      return undefined
355	  }
356	}
357	
358	function AssistantMessageBlock({
359	  param,
360	  addMargin,
361	  tools,
362	  commands,
363	  verbose,
364	  inProgressToolUseIDs,
365	  progressMessagesForMessage,
366	  shouldAnimate,
367	  shouldShowDot,
368	  width,
369	  inProgressToolCallCount,
370	  isTranscriptMode,
371	  lookups,
372	  onOpenRateLimitOptions,
373	  thinkingBlockId,
374	  lastThinkingBlockId,
375	  advisorModel,
376	}: {
377	  param:
378	    | BetaContentBlock
379	    | ConnectorTextBlock
380	    | AdvisorBlock
381	    | TextBlockParam
382	    | ImageBlockParam
383	    | ThinkingBlockParam
384	    | ToolUseBlockParam
385	    | ToolResultBlockParam
386	  addMargin: boolean
387	  tools: Tools
388	  commands: Command[]
389	  verbose: boolean
390	  inProgressToolUseIDs: Set<string>
391	  progressMessagesForMessage: ProgressMessage[]
392	  shouldAnimate: boolean
393	  shouldShowDot: boolean
394	  width?: number | string
395	  inProgressToolCallCount?: number
396	  isTranscriptMode: boolean
397	  lookups: ReturnType<typeof buildMessageLookups>
398	  onOpenRateLimitOptions?: () => void
399	  /** ID of this content block's message:index for thinking block comparison */
400	  thinkingBlockId: string
401	  /** ID of the last thinking block to show, null means show all */
402	  lastThinkingBlockId?: string | null
403	  advisorModel?: string
404	}): React.ReactNode {
405	  if (feature('CONNECTOR_TEXT')) {
406	    if (isConnectorTextBlock(param)) {
407	      return (
408	        <AssistantTextMessage
409	          param={{ type: 'text', text: param.connector_text }}
410	          addMargin={addMargin}
411	          shouldShowDot={shouldShowDot}
412	          verbose={verbose}
413	          width={width}
414	          onOpenRateLimitOptions={onOpenRateLimitOptions}
415	        />
416	      )
417	    }
418	  }
419	  switch (param.type) {
420	    case 'tool_use':
421	      return (
422	        <AssistantToolUseMessage
423	          param={param}
424	          addMargin={addMargin}
425	          tools={tools}
426	          commands={commands}
427	          verbose={verbose}
428	          inProgressToolUseIDs={inProgressToolUseIDs}
429	          progressMessagesForMessage={progressMessagesForMessage}
430	          shouldAnimate={shouldAnimate}
431	          shouldShowDot={shouldShowDot}
432	          inProgressToolCallCount={inProgressToolCallCount}
433	          lookups={lookups}
434	          isTranscriptMode={isTranscriptMode}
435	        />
436	      )
437	    case 'text':
438	      return (
439	        <AssistantTextMessage
440	          param={param}
441	          addMargin={addMargin}
442	          shouldShowDot={shouldShowDot}
443	          verbose={verbose}
444	          width={width}
445	          onOpenRateLimitOptions={onOpenRateLimitOptions}
446	        />
447	      )
448	    case 'redacted_thinking':
449	      if (!isTranscriptMode && !verbose) {
450	        return null
451	      }
452	      return <AssistantRedactedThinkingMessage addMargin={addMargin} />
453	    case 'thinking': {
454	      if (!isTranscriptMode && !verbose) {
455	        return null
456	      }
457	      // In transcript mode with hidePastThinking, only show the last thinking block
458	      const isLastThinking =
459	        !lastThinkingBlockId || thinkingBlockId === lastThinkingBlockId
460	      return (
461	        <AssistantThinkingMessage
462	          addMargin={addMargin}
463	          param={param}
464	          isTranscriptMode={isTranscriptMode}
465	          verbose={verbose}
466	          hideInTranscript={isTranscriptMode && !isLastThinking}
467	        />
468	      )
469	    }
470	    case 'server_tool_use':
471	    case 'advisor_tool_result':
472	      if (isAdvisorBlock(param)) {
473	        return (
474	          <AdvisorMessage
475	            block={param}
476	            addMargin={addMargin}
477	            resolvedToolUseIDs={lookups.resolvedToolUseIDs}
478	            erroredToolUseIDs={lookups.erroredToolUseIDs}
479	            shouldAnimate={shouldAnimate}
480	            verbose={verbose || isTranscriptMode}
481	            advisorModel={advisorModel}
482	          />
483	        )
484	      }
485	      logError(new Error(`Unable to render server tool block: ${param.type}`))
486	      return null
487	    default:
488	      logError(new Error(`Unable to render message type: ${param.type}`))
489	      return null
490	  }
491	}
492	
493	export function hasThinkingContent(m: {
494	  type: string
495	  message?: { content: Array<{ type: string }> }
496	}): boolean {
497	  if (m.type !== 'assistant' || !m.message) return false
498	  return m.message.content.some(
499	    b => b.type === 'thinking' || b.type === 'redacted_thinking',
500	  )
501	}
502	
503	/** Exported for testing */
504	export function areMessagePropsEqual(prev: Props, next: Props): boolean {
505	  if (prev.message.uuid !== next.message.uuid) return false
506	  // Only re-render on lastThinkingBlockId change if this message actually
507	  // has thinking content — otherwise every message in scrollback re-renders
508	  // whenever streaming thinking starts/stops (CC-941).
509	  if (
510	    prev.lastThinkingBlockId !== next.lastThinkingBlockId &&
511	    hasThinkingContent(next.message)
512	  ) {
513	    return false
514	  }
515	  // Verbose toggle changes thinking block visibility/expansion
516	  if (prev.verbose !== next.verbose) return false
517	  // Only re-render if this message's "is latest bash output" status changed,
